/**
 * @file Checks the docs pages for Markdown syntax that Docusaurus won't render.
 *
 * The docs site enables Docusaurus' `future.v4` flag, which turns off MDX 1
 * compatibility. One casualty is the old admonition title syntax: a block such
 * as `:::tip Docs versions` is not parsed as an admonition at all, and the page
 * shows the raw `:::` lines as text without any build error or warning. Titles
 * must use brackets instead, as in `:::tip[Docs versions]`.
 *
 * This script scans every `.md` and `.mdx` page under `docs-site/docs` (except
 * the generated API reference in `docs-site/docs/api`), ignores fenced code
 * blocks so pages can still show the syntax in examples, and reports each
 * old-style admonition title with the line to use instead:
 *
 * ```sh
 * node .github/scripts/check-docs-syntax.mjs
 * ```
 *
 * It exits with code 1 if it finds any.
 */

import { readdirSync, readFileSync } from "node:fs";
import { relative, resolve } from "node:path";

/** Absolute path of the repository root (two levels above this script). */
const ROOT = resolve(import.meta.dirname, "../..");

/** Directory holding the docs pages. */
const DOCS_DIR = resolve(ROOT, "docs-site/docs");

/** Generated by docusaurus-plugin-typedoc and gitignored, so never checked. */
const GENERATED_DIR = resolve(DOCS_DIR, "api");

/**
 * An admonition opening line with a title after a space, such as
 * `:::tip Docs versions`. Group 1 is the indentation, 2 the type and 3 the
 * title.
 */
const OLD_TITLE = /^(\s*):::([a-z]+)\s+(\S.*?)\s*$/;

/** The opening line of a fenced code block: three or more backticks or tildes. */
const FENCE = /^\s*(`{3,}|~{3,})/;

/**
 * Lists every Markdown page under a directory.
 *
 * @param dir - Absolute path of the directory to search.
 * @returns Absolute paths of its `.md` and `.mdx` files, in nested order.
 */
const listPages = (dir) =>
  readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const path = resolve(dir, entry.name);
    if (entry.isDirectory()) {
      return path === GENERATED_DIR ? [] : listPages(path);
    }
    return /\.mdx?$/.test(entry.name) ? [path] : [];
  });

/**
 * Finds old-style admonition titles in one page.
 *
 * @param source - The page's full text.
 * @returns One problem per offending line, with its 1-based line number.
 */
const findOldTitles = (source) => {
  const problems = [];
  /** The fence that opened the current code block, or `null` outside one. */
  let openFence = null;

  source.split("\n").forEach((line, index) => {
    const fence = FENCE.exec(line);
    if (fence) {
      // A block closes on a fence of the same character that is at least as
      // long as the one that opened it, per CommonMark.
      if (openFence === null) openFence = fence[1];
      else if (
        fence[1][0] === openFence[0] &&
        fence[1].length >= openFence.length
      ) {
        openFence = null;
      }
      return;
    }
    if (openFence !== null) return;

    const match = OLD_TITLE.exec(line);
    if (match) {
      const [, indent, type, title] = match;
      problems.push({
        line: index + 1,
        found: line.trim(),
        fix: `${indent}:::${type}[${title}]`.trim(),
      });
    }
  });

  return problems;
};

/** Runs the check on every page and reports the results. */
const main = () => {
  const pages = listPages(DOCS_DIR);
  let count = 0;

  for (const page of pages) {
    const problems = findOldTitles(readFileSync(page, "utf8"));
    if (problems.length === 0) continue;
    console.error(`\n${relative(ROOT, page)}`);
    for (const { line, found, fix } of problems) {
      console.error(
        `  - line ${line}: \`${found}\` won't render; use \`${fix}\``
      );
    }
    count += problems.length;
  }

  if (count === 0) {
    console.log(
      `All ${pages.length} docs pages use supported admonition syntax.`
    );
    return;
  }

  console.error(
    `\n${count} admonition title(s) use the MDX 1 syntax, which the docs site's future.v4 flag doesn't support.`
  );
  process.exitCode = 1;
};

main();
